import random

def generate_test_case():
    k = random.randint(0, 10)
    lists = []
    for _ in range(k):
        current_list = sorted([random.randint(-100, 100) for _ in range(random.randint(0, 100))])
        if len(lists) + len(current_list) < 1000:
            lists.append(current_list)
        else:
